  "COLW": { doc: "ARCADE_LANGUAGE_BATCH3.md", anchor: "the-words", example: "GAME \"Vault\"\nFRAMERATE 20\nTILESET gfx = \"gfx\"\nMAP plan = \"plan\"\nVIEW3D plan COLW 4 INK 5 CEIL 0 FLOOR 1\nSCENE play\n  DIM px, py, pa\n  PROC INIT():\n    px = 4 * 256 + 128 : py = 4 * 256 + 128\n  ENDP\n  PROC FRAME():\n    pa = pa + 1\n    VIEW px, py, pa\n  ENDP\nENDSCENE" },
