  "USING": { doc: "ARCADE_LANGUAGE_BATCH5.md", anchor: "part-b-print-formatting-item-7", example: "PRINT AT 0, 0; score USING \"00000\";   REM 00042\nPRINT AT 1, 0; lives USING \"##\";       REM \" 3\"" },
  "NOWINDOW": { doc: "ARCADE_LANGUAGE_BATCH7.md", anchor: "1-the-language", example: "GAME \"Runner\"\nFRAMERATE 30\nTILESET tiles = \"tiles\"\nMAP level = \"level\"\nWINDOW level\nSCENE title NOWINDOW         REM the whole screen, no scrolling window\n  PROC INIT():\n    PRINT AT 11, 10; \"LEAP RUNNER\";\n  ENDP\n  PROC FRAME():\n    IF KEYPRESS(\" \") THEN ENTER play ENDIF\n  ENDP\nENDSCENE\nSCENE play                   REM this scene shows the window again\n  PROC INIT():\n    CAMERA 0\n  ENDP\n  PROC FRAME():\n    CAMERA CAMX() + 1\n  ENDP\nENDSCENE" },
  "NOVIEW": { doc: "ARCADE_LANGUAGE_BATCH7.md", anchor: "1-the-language", example: "GAME \"Vault\"\nFRAMERATE 20\nTILESET gfx = \"gfx\"\nMAP plan = \"plan\"\nVIEW3D plan COLW 4 INK 5 CEIL 0 FLOOR 1\nSCENE title NOVIEW           REM the whole screen, no 3D view\n  PROC INIT():\n    PRINT AT 11, 12; \"VAULT\";\n  ENDP\n  PROC FRAME():\n    IF KEYPRESS(\" \") THEN ENTER play ENDIF\n  ENDP\nENDSCENE\nSCENE play                   REM this scene shows the 3D view again\n  DIM pa\n  PROC INIT():\n    pa = 0\n  ENDP\n  PROC FRAME():\n    pa = pa + 1\n    VIEW 1152, 1152, pa\n  ENDP\nENDSCENE" },
  "ROWS": { doc: "ARCADE_WIREFRAME_CONTRACT.md", anchor: "1-the-language", example: "GAME \"Wires\"\nFRAMERATE 30\nMODEL gate = \"gate\"\nWIRE3D ROWS 2 TO 21 INK 5 PAPER 0 BRIGHT 0\nSCENE fly\n  DIM a\n  PROC INIT():\n    a = 0\n  ENDP\n  PROC FRAME():\n    a = a + 2\n    EYE 0, 0, 0, 0\n    DRAWMODEL gate AT 0, 0, 500 YAW a SCALE 2\n  ENDP\nENDSCENE" },
